 */
public object FfiConverterTypeMasterKeyHandle: FfiConverter<MasterKeyHandle, Long> {
    override fun lower(value: MasterKeyHandle): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): MasterKeyHandle {
        return MasterKeyHandle(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): MasterKeyHandle {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MasterKeyHandle) = 8UL

    override fun write(value: MasterKeyHandle, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * Result of encrypting a chunk or metadata. Contains the cipher suite
 * identifier, a random nonce, and the ciphertext (including the GCM tag).
 */
data class EncryptedData (
    var `cipherSuite`: kotlin.String
    , 
    var `nonce`: kotlin.ByteArray
    , 
    var `ciphertext`: kotlin.ByteArray
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeEncryptedData: FfiConverterRustBuffer<EncryptedData> {
    override fun read(buf: ByteBuffer): EncryptedData {
        return EncryptedData(
            FfiConverterString.read(buf),
            FfiConverterByteArray.read(buf),
            FfiConverterByteArray.read(buf),
        )
    }

    override fun allocationSize(value: EncryptedData) = (
            FfiConverterString.allocationSize(value.`cipherSuite`) +
            FfiConverterByteArray.allocationSize(value.`nonce`) +
            FfiConverterByteArray.allocationSize(value.`ciphertext`)
    )

    override fun write(value: EncryptedData, buf: ByteBuffer) {
            FfiConverterString.write(value.`cipherSuite`, buf)
            FfiConverterByteArray.write(value.`nonce`, buf)
            FfiConverterByteArray.write(value.`ciphertext`, buf)
    }
}



