sealed class CryptoException: kotlin.Exception() {
    
    class Encryption(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Decryption(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class Kdf(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidRecoveryPhrase(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class InvalidInput(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Opaque(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CryptoException> {
        override fun lift(error_buf: RustBuffer.ByValue): CryptoException = FfiConverterTypeCryptoError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCryptoError : FfiConverterRustBuffer<CryptoException> {
    override fun read(buf: ByteBuffer): CryptoException {
        

        return when(buf.getInt()) {
            1 -> CryptoException.Encryption(
                FfiConverterString.read(buf),
                )
            2 -> CryptoException.Decryption()
            3 -> CryptoException.Kdf(
                FfiConverterString.read(buf),
                )
            4 -> CryptoException.InvalidRecoveryPhrase()
            5 -> CryptoException.InvalidInput(
                FfiConverterString.read(buf),
                )
            6 -> CryptoException.Opaque(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CryptoException): ULong {
        return when(value) {
            is CryptoException.Encryption -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CryptoException.Decryption -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CryptoException.Kdf -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CryptoException.InvalidRecoveryPhrase -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CryptoException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CryptoException.Opaque -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: CryptoException, buf: ByteBuffer) {
        when(value) {
            is CryptoException.Encryption -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CryptoException.Decryption -> {
                buf.putInt(2)
                Unit
            }
            is CryptoException.Kdf -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CryptoException.InvalidRecoveryPhrase -> {
                buf.putInt(4)
                Unit
            }
            is CryptoException.InvalidInput -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CryptoException.Opaque -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}
